//Hija de Dispositivo, y se implementan las interfaces regulable, controlable, medible y alertable

public class Climatizador extends Dispositivo implements Controlable, Regulable, Medible, Alertable {
    // Atributos nuevos
    protected int nivel;
    protected double temperatura;


    // Constructor default
    public Climatizador() {
        super();
        nivel = 50;
        temperatura = 0;
    }

    // Constructor completo
    public Climatizador(String codigo, Oficina oficina, double potenciaNominal) {
        super(codigo, oficina, potenciaNominal);
        nivel = 50;
        temperatura = 0;
    }


    // Getters de los nuevos atributos
    public int getNivel() {
        return nivel;
    }
    public double getTemperatura() {
        return temperatura;
    }


    // Endencer dispositivo
    @Override
    public boolean encender() {

        if (encendido) {
            return false;
        }

        encendido = true;
        return true;
    }


    // Apagar el dispositivo
    @Override
    public boolean apagar() {

        if (!encendido) {
            return false;
        }

        encendido = false;
        return true;
    }


    // Ajustar nivel solo entre 20 y 100
    @Override
    public boolean ajustarNivel(int nivel) {

        if (!encendido) {
            return false;
        }

        if (nivel < 20 || nivel > 100) {
            return false;
        }

        this.nivel = nivel;
        return true;
    }


    // Registrar la lectura del método Medible, verifica que este encendido y que sea entre -10 y 60 grados

    @Override
    public int registrarLectura(double valor) {

        if (!encendido) {
			//El código inválido es -1
            return -1;
        }

        if (valor < -10 || valor > 60 || Double.isNaN(valor) || Double.isInfinite(valor)) {
            return -1;
        }

        // Guarda la lectura solamente si es valida
        temperatura = valor;

        // Critica
        if (valor >= 40) {
            return 3;
        }

        // Alta
        else if (valor >= 32) {
            return 2;
        }

        // Baja
        else if (valor >= 28) {
            return 1;
        }

        // Temperatura normal
        return 0;
    }


    // Genera alerta según el código, genererará una severidad, y con ella, también se chequeará la hora de simulación
    @Override
    public Alerta generarAlerta(int codigo, Severidad severidad, int horaSimulacion) {

        if (severidad == null || codigo <= 0 || horaSimulacion < 0) {
            return null;
        }

        String mensaje = "Temperatura de " + temperatura + " grados Celsius registrada por el climatizador " + this.codigo;

        return new Alerta(codigo, this, horaSimulacion, severidad, mensaje);
    }


    // Calcular consumo por hora con la siguiente formula

    @Override
    public double calcularConsumoHora() {
        if (!encendido) {
            return 0;
        }

        return (potenciaNominal * (0.30 + 0.70 * nivel / 100.0)) / 1000.0;
		//Divido entre 1000 por kW
    }


    // toString + lo nuevo

    @Override
    public String toString() {
        return super.toString()
                + "\nNivel de intensidad: " + nivel + "%"
                + "\nUltima temperatura: " + temperatura + " grados Celsius";
    }
}
